head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > rowNumData]<br/>JSON 또는 XML 형식으로 Row 데이터를 반환하는 get 계열의 메소드에서 반환값에 Row 의 순번을 추가할지 설정합니다.",
    "validation" : [
        "JSON 형식으로 Row 데이터를 반환하는 get 계열의 메소드에서 반환값에 Row 의 순번을 추가할지 설정합니다.",
        "미설정 또는 false 설정 시 get 계열의 메소드 반환값에 Row 의 순번을 의미하는 rowNum 속성을 추가하지 않습니다.",
        "true 설정 시 get 계열의 메소드 반환값에 Row 의 순번을 의미하는 rowNum 속성을 추가합니다.",
        "Row 의 순번은 일반적으로 Row 의 인덱스에 1을 더한 값입니다.",
        "메소드에 따라 반환값에 필터링/정렬이 적용된 경우 Row 의 순번도 필터링/정렬이 적용된 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        rowNumData : con_rowNumData.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList(cList);

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();

    isFilter = false;
    isSort = false;
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})        
        isFilter = true;
    }	

    scwin.btn_getAllFilteredJSON_onclick();
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }

    scwin.btn_getAllFilteredJSON_onclick();
};



scwin.btn_getAllFilteredJSON_onclick = function (e) {
    let rtn = target1.getAllFilteredJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};
